insert into public.question_bank (teks_code, teks_item_id, subject, grade_num, course, difficulty, qtype, prompt, choices, answer_idx, explanation, source, status, gen_batch)
select distinct on (v.prompt) v.code, i.id, d.subject,
       case when i.grade_level = 'K' then 0 when i.grade_level ~ '^[0-9]+' then substring(i.grade_level from '^[0-9]+')::smallint end,
       case when i.grade_level is null then i.grade_course_title end,
       v.diff, 'mc', v.prompt, v.choices, v.ans, v.expl, v.src, 'checked', 'cte_58_v1'
from (values
('127.394.d.1.A',3,'A technician knows a circuit board needs 24 resistors. For a run of 150 boards, how many resistors are needed?','["3,600", "3,000", "360", "174"]'::jsonb,0,'24 x 150 = 3,600.','original'),
('127.394.d.1.A',4,'A shop pays $0.12 per connector and needs 250. With a 10 percent discount, the total cost is:','["$30.00", "$27.00", "$29.88", "$3.00"]'::jsonb,1,'250 x 0.12 = 30; 10% off leaves 27.','original'),
('127.394.d.1.B',3,'The last step in a problem-solving model is to:','["skip checking", "delete the work", "evaluate the reasonableness of the solution", "pick a new problem"]'::jsonb,2,'A solution must be checked for reasonableness.','original'),
('127.394.d.1.B',4,'In a problem-solving model, formulating a plan comes after:','["presenting results", "justifying the solution", "evaluating the process", "analyzing the given information"]'::jsonb,3,'You must understand the data before planning.','original'),
('127.394.d.1.C',3,'To check whether 49 x 21 is close to 1,000 without a calculator, a good technique is:','["rounding to 50 x 20", "adding the digits", "multiplying by 0", "guessing"]'::jsonb,0,'50 x 20 = 1,000, so the estimate is reasonable.','original'),
('127.394.d.1.C',4,'To compute many resistor-network values accurately, the best tool is usually:','["a stopwatch", "a calculator or spreadsheet", "a ruler", "mental guessing only"]'::jsonb,1,'Technology reduces arithmetic errors.','original'),
('127.394.d.1.D',3,'A graph, a table, and an equation are all examples of mathematical:','["tolerances", "constraints", "representations", "errors"]'::jsonb,2,'Multiple representations communicate ideas.','original'),
('127.394.d.1.D',4,'To explain to a coworker how a voltage changes over time, which representation is clearest?','["A blank table", "A random list", "A sentence with no numbers", "A labeled graph"]'::jsonb,3,'Graphs show change clearly.','original'),
('127.394.d.1.E',3,'Recording measured voltages in a table helps a technician to:','["organize and compare data", "hide data", "avoid units", "lose accuracy"]'::jsonb,0,'Tables organize measurements.','original'),
('127.394.d.1.E',4,'A timing diagram is a representation used to show how digital signals:','["are colored", "change over time", "are shipped", "are priced"]'::jsonb,1,'Timing diagrams plot logic levels against time.','original'),
('127.394.d.1.F',3,'If doubling the input always doubles the output, the relationship is:','["constant", "random", "proportional", "inverse"]'::jsonb,2,'Constant ratio means proportional.','original'),
('127.394.d.1.F',4,'As the resistance in a circuit increases at constant voltage, the current:','["stays the same", "increases", "doubles", "decreases"]'::jsonb,3,'I = V / R, an inverse relationship.','original'),
('127.394.d.1.G',3,'When justifying a calculation, you should use:','["precise mathematical language", "slang", "guesses", "vague terms"]'::jsonb,0,'Justification requires precise terms.','original'),
('127.394.d.1.G',4,'A strong justification of a measurement result includes the work and the:','["color of the paper", "reasoning behind each step", "name of the calculator", "time of day"]'::jsonb,1,'Reasoning shows why the answer is valid.','original'),
('127.394.d.2.A',3,'Who typically designs new systems and does advanced analysis requiring a four-year engineering degree?','["A receptionist", "A courier", "An engineer", "An assembler"]'::jsonb,2,'Engineers design and analyze systems.','original'),
('127.394.d.2.A',4,'Compared with an engineer, an engineering technician typically focuses more on:','["teaching history", "writing laws", "setting company stock prices", "building, testing, and maintaining systems"]'::jsonb,3,'Technicians implement and support designs.','original'),
('127.394.d.2.B',3,'Which industry hires digital electronics technicians?','["Computer and communications equipment manufacturing", "Lumber milling", "Retail clothing", "Dairy farming"]'::jsonb,0,'Digital electronics is core to computing and communications.','original'),
('127.394.d.2.B',4,'A job title for someone who tests and troubleshoots circuit boards is:','["crossing guard", "test technician", "court clerk", "florist"]'::jsonb,1,'Test technicians verify boards work.','original'),
('127.394.d.2.C',3,'Passing an industry certification exam shows an employer that you have:','["paid a fee only", "finished high school", "validated technical knowledge", "joined a club"]'::jsonb,2,'Certification verifies skill.','original'),
('127.394.d.2.C',4,'Which type of credential is awarded by an industry group rather than a school?','["Report card", "Honor roll", "Diploma", "Industry certification"]'::jsonb,3,'Industry groups award certifications.','original'),
('127.394.d.2.D',3,'Using someone else''s source code in your project without credit is:','["plagiarism", "collaboration", "innovation", "debugging"]'::jsonb,0,'Uncredited use of others'' work is plagiarism.','original'),
('127.394.d.2.D',4,'An engineer''s primary ethical duty when public safety is at risk is to:','["blame a coworker", "put public safety first", "hide the issue", "protect company profit"]'::jsonb,1,'Engineering codes put public safety first.','original'),
('127.394.d.2.E',3,'A team with members from different cultures and experiences is likely to produce:','["no ideas", "identical ideas", "a wider range of ideas", "fewer ideas"]'::jsonb,2,'Diversity broadens perspective.','original'),
('127.394.d.2.E',4,'Respectful behavior toward coworkers with different backgrounds includes:','["interrupting them", "mocking accents", "excluding them", "listening to their ideas"]'::jsonb,3,'Respect means listening.','original'),
('127.394.d.2.F',3,'A company can be fined if it allows:','["illegal workplace discrimination", "safe work", "on-time delivery", "fair hiring"]'::jsonb,0,'Discrimination violates employment law.','original'),
('127.394.d.2.F',4,'An employee who experiences harassment at work can file a complaint with the:','["Postal Service", "Equal Employment Opportunity Commission", "Weather Service", "Forest Service"]'::jsonb,1,'The EEOC enforces anti-discrimination law.','original'),
('127.394.d.2.G',3,'A bachelor''s degree in electrical engineering commonly takes:','["one week", "ten years", "four years", "six months"]'::jsonb,2,'Bachelor''s degrees take about four years.','original'),
('127.394.d.2.G',4,'An associate degree program in electronics usually takes about:','["one month", "six years", "a weekend", "two years"]'::jsonb,3,'Associate degrees take about two years.','original'),
('127.394.d.2.H',3,'A mentorship pairs a student with:','["an experienced professional", "a vendor", "a new classmate", "no one"]'::jsonb,0,'Mentors guide students from experience.','original'),
('127.394.d.2.H',4,'A benefit of a summer internship at an electronics company is:','["guaranteed degree", "hands-on experience and industry contacts", "free equipment", "no responsibility"]'::jsonb,1,'Internships build skills and networks.','original'),
('127.394.d.2.I',3,'Programs accredited by ABET are reviewed to ensure they meet:','["sports rules", "cooking guidelines", "professional education standards", "fashion trends"]'::jsonb,2,'Accreditation checks program quality.','original'),
('127.394.d.2.I',4,'ABET accreditation matters most to students who plan to:','["avoid college", "skip exams", "retire early", "pursue jobs that require an accredited degree"]'::jsonb,3,'Many employers and licenses require accredited degrees.','original'),
('127.394.d.3.A',3,'In building a digital product, one person designs the logic and another writes the code. Their work succeeds if they:','["agree on the interface between them", "never meet", "hide changes", "use different standards"]'::jsonb,0,'Teams must agree on how parts connect.','original'),
('127.394.d.3.A',4,'Teams reduce design errors when members:','["skip reviews", "review each other''s work", "work in isolation", "reuse errors"]'::jsonb,1,'Peer review catches mistakes.','original'),
('127.394.d.3.B',3,'When a team''s circuit fails a test, the team should first:','["stop testing", "assign blame", "gather data about the failure", "buy new parts"]'::jsonb,2,'Data guides the fix.','original'),
('127.394.d.3.B',4,'Brainstorming rules usually say that during idea generation, ideas should be:','["rejected at once", "hidden", "graded", "collected without criticism"]'::jsonb,3,'Judgment comes after collection.','original'),
('127.394.d.3.C',3,'A positive attitude on a project team includes:','["accepting feedback", "gossiping", "ignoring deadlines", "resisting all feedback"]'::jsonb,0,'Openness to feedback improves work.','original'),
('127.394.d.3.C',4,'A team leader earns respect by:','["taking credit", "setting an example of reliability", "dodging work", "avoiding decisions"]'::jsonb,1,'Leaders model dependable behavior.','original'),
('127.394.d.4.A',3,'In project management, executing the project means:','["writing the manual only", "choosing a name", "carrying out the planned work", "shipping unfinished work"]'::jsonb,2,'Execution performs the plan.','original'),
('127.394.d.4.A',4,'Which project phase compares actual progress with the schedule and budget?','["Closing", "Initiating", "Brainstorming", "Monitoring and controlling"]'::jsonb,3,'Monitoring tracks performance against the plan.','original'),
('127.394.d.4.B',3,'If one task cannot start until another finishes, the tasks have a:','["dependency", "margin", "duplicate", "summary"]'::jsonb,0,'Dependent tasks are sequenced.','original'),
('127.394.d.4.B',4,'Adding buffer time to a schedule helps the team handle:','["fewer tasks", "unexpected delays", "lower quality", "paid holidays"]'::jsonb,1,'Buffers absorb surprises.','original'),
('127.394.d.4.C',3,'In a student company that builds logic trainers, the marketing team would:','["solder every board", "inspect wiring only", "promote and sell the product", "design chips"]'::jsonb,2,'Marketing promotes and sells.','original'),
('127.394.d.4.C',4,'A mission statement for a school enterprise describes its:','["monthly expenses", "employee salaries", "building plans", "purpose and goals"]'::jsonb,3,'Mission states purpose.','original'),
('127.394.d.4.D',3,'A production plan for a logic trainer should identify the parts list and the:','["assembly sequence", "uniform color", "lunch menu", "bus route"]'::jsonb,0,'Plans list parts and steps.','original'),
('127.394.d.4.D',4,'Deciding how many units to build before ordering parts helps avoid:','["labeling", "buying too many or too few parts", "soldering", "testing"]'::jsonb,1,'Quantity planning prevents waste and shortages.','original'),
('127.394.d.5.A',3,'Why must a student pass the safety exam before using soldering irons in the digital electronics lab?','["The exam is a fee", "Irons are free", "Hot tools and fumes can injure unprepared users", "Safety rules are secret"]'::jsonb,2,'Training prevents injuries.','original'),
('127.394.d.5.A',4,'A safety test result of 100 percent shows that a student:','["is immune to accidents", "may ignore signs", "can skip supervision", "has demonstrated the required safety knowledge"]'::jsonb,3,'It verifies knowledge, not immunity.','original'),
('127.394.d.5.B',3,'The safety information in an equipment manual should be read:','["before first use", "after the warranty ends", "after an injury", "never"]'::jsonb,0,'Read safety instructions before using equipment.','original'),
('127.394.d.5.B',4,'Before replacing a fuse in a bench instrument, the manual says to first:','["spray cleaner", "unplug the instrument", "touch the board", "run it hotter"]'::jsonb,1,'Remove power before servicing.','original'),
('127.394.d.5.C',3,'What do OSHA standards create for employers?','["Optional suggestions", "Pricing guides", "Legal workplace safety requirements", "Dress codes"]'::jsonb,2,'OSHA rules are enforceable.','original'),
('127.394.d.5.C',4,'The Occupational Safety and Health Administration is part of the U.S. Department of:','["Defense", "Agriculture", "Education", "Labor"]'::jsonb,3,'OSHA is under the Department of Labor.','original'),
('127.394.d.5.D',3,'A Safety Data Sheet (SDS) for flux or solder lists the product''s:','["hazards and handling precautions", "color only", "shipping rate", "sale price"]'::jsonb,0,'SDSs describe hazards and precautions.','original'),
('127.394.d.5.D',4,'Flux fumes from soldering should be controlled with:','["an open flame", "ventilation or a fume extractor", "more heat", "closed windows"]'::jsonb,1,'Ventilation removes harmful fumes.','original'),
('127.394.d.5.E',3,'Spent solder wick and solder dross should be put in:','["the sink", "a backpack", "a labeled waste container", "a classmate''s workspace"]'::jsonb,2,'Solder waste needs proper containers.','original')
) as v(code, diff, prompt, choices, ans, expl, src)
join public.teks_items i on i.code = v.code and i.is_standard
join public.teks_documents d on d.id = i.document_id and d.subject = 'Career Development' and d.language = 'en'
on conflict (fingerprint) do nothing;
insert into public.question_bank (teks_code, teks_item_id, subject, grade_num, course, difficulty, qtype, prompt, choices, answer_idx, explanation, source, status, gen_batch)
select distinct on (v.prompt) v.code, i.id, d.subject,
       case when i.grade_level = 'K' then 0 when i.grade_level ~ '^[0-9]+' then substring(i.grade_level from '^[0-9]+')::smallint end,
       case when i.grade_level is null then i.grade_course_title end,
       v.diff, 'mc', v.prompt, v.choices, v.ans, v.expl, v.src, 'checked', 'cte_58_v1'
from (values
('127.394.d.5.E',4,'Old integrated circuits and boards should be recycled rather than thrown away because they contain:','["only paper", "only air", "only water", "metals that can harm the environment"]'::jsonb,3,'E-waste contains toxic metals.','original'),
('127.394.d.5.F',3,'A dull wire cutter should be:','["sharpened or replaced", "used anyway", "forced harder", "painted"]'::jsonb,0,'Dull tools are less safe.','original'),
('127.394.d.5.F',4,'Cleaning flux residue from a circuit board helps prevent:','["stronger solder", "corrosion and leakage current", "color change", "louder buzzers"]'::jsonb,1,'Residue can corrode and conduct.','original'),
('127.394.d.5.G',3,'Static-sensitive ICs should be handled by their edges while wearing:','["a rubber apron", "wool gloves", "a grounded wrist strap", "a metal necklace"]'::jsonb,2,'A grounded strap prevents ESD damage.','original'),
('127.394.d.5.G',4,'Tools should be returned to their labeled storage so that:','["nobody can find them", "they become lost", "they rust faster", "they are easy to find and inventory"]'::jsonb,3,'Organized storage saves time and prevents loss.','original'),
('127.394.d.5.H',3,'A dull drill bit forced through a board can cause:','["slips, damage, or injury", "quieter work", "perfect holes", "faster safe drilling"]'::jsonb,0,'Dull bits bind and slip.','original'),
('127.394.d.5.H',4,'Not replacing a cracked soldering iron stand could lead to:','["fewer hazards", "burns or fires", "cooler tools", "better soldering"]'::jsonb,1,'A bad stand lets a hot iron fall or touch materials.','original'),
('127.394.d.6.A',3,'The SI prefix kilo means:','["one hundred", "one billionth", "one thousand", "one million"]'::jsonb,2,'Kilo = 10^3.','original'),
('127.394.d.6.A',4,'A capacitor value of 0.000001 farads can be written as:','["1 picofarad", "1 millifarad", "1 nanofarad", "1 microfarad"]'::jsonb,3,'Micro = 10^-6.','original'),
('127.394.d.6.B',3,'A good solder joint looks:','["smooth and shiny", "dull and cracked", "burned black", "lumpy and ball-shaped"]'::jsonb,0,'Good joints are smooth, shiny, and concave.','original'),
('127.394.d.6.B',4,'A cold solder joint is usually caused by:','["a clean joint", "not enough heat reaching the joint", "a tinned iron tip", "too much flux"]'::jsonb,1,'Insufficient heat prevents proper wetting.','original'),
('127.394.d.6.C',3,'A digital signal typically has how many distinct voltage levels?','["Hundreds", "Infinite", "Two", "Ten"]'::jsonb,2,'Digital signals use HIGH and LOW.','original'),
('127.394.d.6.C',4,'Which waveform is smooth and continuously varying?','["Clock signal", "Digital square wave", "Pulse train", "Analog sine wave"]'::jsonb,3,'Analog signals vary continuously.','original'),
('127.394.d.6.D',3,'In 5 V TTL logic, a logic HIGH is typically near:','["5 volts", "0 volts", "9 volts", "12 volts"]'::jsonb,0,'TTL HIGH is close to the supply.','original'),
('127.394.d.6.D',4,'A voltage between the valid LOW and valid HIGH ranges is considered:','["ideal", "indeterminate", "always LOW", "always HIGH"]'::jsonb,1,'Such voltages give unpredictable logic results.','original'),
('127.394.d.6.E',3,'Silicon, used in transistors, is classified as a:','["conductor", "superconductor", "semiconductor", "insulator"]'::jsonb,2,'Silicon conducts under controlled conditions.','original'),
('127.394.d.6.E',4,'Rubber and glass are good:','["semiconductors", "conductors", "magnets", "insulators"]'::jsonb,3,'They resist current flow.','original'),
('127.394.d.6.F',3,'Which quantity is the push that causes current to flow?','["Voltage", "Inductance", "Resistance", "Capacitance"]'::jsonb,0,'Voltage is electrical pressure.','original'),
('127.394.d.6.F',4,'If voltage stays fixed and resistance doubles, current becomes:','["four times larger", "half as large", "twice as large", "the same"]'::jsonb,1,'I = V / R.','original'),
('127.394.d.6.G',3,'Circuit design software is used to:','["bake components", "clean tools", "draw schematics and simulate circuits", "print money"]'::jsonb,2,'EDA tools capture and test designs.','original'),
('127.394.d.6.G',4,'A benefit of simulating a digital circuit before building it is that errors can be:','["hidden", "ignored", "made permanent", "found without damaging parts"]'::jsonb,3,'Simulation is safe testing.','original'),
('127.394.d.6.H',3,'The basic one-bit memory element used in sequential logic is the:','["flip-flop", "inverter", "resistor", "fuse"]'::jsonb,0,'Flip-flops store one bit.','original'),
('127.394.d.6.H',4,'Unlike combinational circuits, sequential circuits have outputs that depend on inputs and:','["wire color", "past states", "supplier", "room temperature"]'::jsonb,1,'Sequential circuits have memory.','original'),
('127.394.d.6.I',3,'A manufacturer''s datasheet for an IC includes a pinout, electrical characteristics, and a:','["price list only", "personal letter", "logic diagram or function table", "map"]'::jsonb,2,'Datasheets document function.','original'),
('127.394.d.6.I',4,'Which datasheet section gives the highest voltage a chip can safely withstand?','["Ordering history", "Package color", "Marketing blurb", "Absolute maximum ratings"]'::jsonb,3,'Exceeding these ratings can damage the chip.','original'),
('127.394.d.6.J',3,'ICs with only a few gates are classified as:','["small-scale integration", "very large-scale integration", "ultra-large memory", "giga-scale integration"]'::jsonb,0,'SSI chips hold a handful of gates.','original'),
('127.394.d.6.J',4,'Which logic technology draws almost no static power?','["Diode logic", "CMOS", "TTL", "Relay logic"]'::jsonb,1,'CMOS uses power mainly when switching.','original'),
('127.394.d.6.K',3,'Compared with standard TTL, low-power Schottky (LS) TTL has the advantage of:','["needing no supply", "higher power consumption", "lower power consumption", "larger size"]'::jsonb,2,'LS saves power.','original'),
('127.394.d.6.K',4,'A disadvantage of CMOS devices is their:','["need for 100 V", "slow supply", "high static power draw", "sensitivity to static discharge"]'::jsonb,3,'CMOS gates are easily damaged by ESD.','original'),
('127.394.d.6.L',3,'The Boolean expression for a 2-input AND gate is:','["Y = A . B", "Y = A XOR B", "Y = A + B", "Y = NOT A"]'::jsonb,0,'AND is the product.','original'),
('127.394.d.6.L',4,'A gate whose output is HIGH only when its two inputs differ is the:','["OR gate", "XOR gate", "AND gate", "NAND gate"]'::jsonb,1,'XOR means exclusive OR.','original'),
('127.394.d.6.M',3,'In a combinational circuit, the output depends only on:','["the clock history", "stored states", "the current inputs", "previous outputs"]'::jsonb,2,'Combinational circuits have no memory.','original'),
('127.394.d.6.M',4,'A 4-input combinational circuit has how many possible input combinations?','["12", "8", "4", "16"]'::jsonb,3,'2^4 = 16.','original'),
('127.394.d.6.N',3,'The expression Y = A''B + AB'' can be built from AND, OR, and:','["NOT gates", "memory cells", "counters", "clock pulses"]'::jsonb,0,'The primes require inverters.','original'),
('127.394.d.6.N',4,'A 2-input AND gate has A = 1 and B = 0. Its output is:','["HIGH (1)", "LOW (0)", "undefined", "both 0 and 1"]'::jsonb,1,'AND needs both inputs HIGH.','original'),
('127.394.d.6.O',3,'A flip-flop stores how many bits of information?','["Sixteen", "Zero", "One", "Eight"]'::jsonb,2,'A flip-flop is a one-bit memory.','original'),
('127.394.d.6.O',4,'Flip-flops change state in response to a:','["fuse rating", "wire length", "paint color", "clock edge"]'::jsonb,3,'Edge-triggered devices update on the clock.','original'),
('127.394.d.7.A',3,'The binary number 1011 equals what decimal number?','["11", "13", "9", "10"]'::jsonb,0,'8 + 2 + 1 = 11.','original'),
('127.394.d.7.A',4,'The decimal number 25 in binary is:','["11010", "11001", "10101", "10011"]'::jsonb,1,'16 + 8 + 1 = 25.','original'),
('127.394.d.7.B',3,'A truth table for 2 inputs has how many rows?','["8", "2", "4", "3"]'::jsonb,2,'2^2 = 4.','original'),
('127.394.d.7.B',4,'To translate a design specification into a truth table, you first list every possible combination of:','["output wires", "power sources", "clock chips", "input values"]'::jsonb,3,'Rows enumerate input combinations.','original'),
('127.394.d.7.C',3,'To write a sum-of-products expression from a truth table, include a product term for each row where the output is:','["1", "unknown", "X", "0"]'::jsonb,0,'Each 1-row yields a minterm.','original'),
('127.394.d.7.C',4,'A truth table row with A = 1, B = 0 and output 1 produces the product term:','["A'' B", "A B''", "A + B''", "A'' + B"]'::jsonb,1,'A true, B complemented.','original'),
('127.394.d.7.D',3,'Sum-of-products form is a group of AND terms combined by:','["NOT", "NAND only", "OR", "clock"]'::jsonb,2,'SOP ORs product terms.','original'),
('127.394.d.7.D',4,'Product-of-sums form is a group of OR terms combined by:','["clock", "buffer", "NOT", "AND"]'::jsonb,3,'POS ANDs sum terms.','original'),
('127.394.d.7.E',3,'Any Boolean expression can be built using only AND, OR, and NOT gates because they form a:','["complete set", "noisy set", "memory set", "power set"]'::jsonb,0,'They are functionally complete.','original'),
('127.394.d.7.E',4,'A logic expression that is not simplified will still work, but it may require:','["negative voltage", "more gates than necessary", "fewer gates", "no gates"]'::jsonb,1,'Simplification reduces cost.','original'),
('127.394.d.7.F',3,'In the formal digital design process, after writing the truth table you typically:','["ship the circuit", "skip testing", "derive and simplify the logic expression", "order a case"]'::jsonb,2,'Next comes the expression.','original'),
('127.394.d.7.F',4,'The last step in the formal design process is to:','["define the problem", "draw the first sketch", "order more parts", "test the circuit against the specification"]'::jsonb,3,'Verification closes the process.','original'),
('127.394.d.8.A',3,'A Karnaugh map is used to:','["simplify Boolean expressions", "measure voltage", "count clock pulses", "draw wires"]'::jsonb,0,'K-maps group adjacent 1s.','original'),
('127.394.d.8.A',4,'When grouping 1s on a K-map, each group must contain a number of cells that is a:','["multiple of three", "power of two", "prime number", "odd number"]'::jsonb,1,'Groups are 1, 2, 4, 8, or 16.','original'),
('127.394.d.8.B',3,'In a truth table, a don''t-care output is marked with:','["a one only", "a minus", "an X", "a zero only"]'::jsonb,2,'X means either value is acceptable.','original'),
('127.394.d.8.B',4,'A don''t-care condition is useful because it can be treated as 0 or 1 to:','["increase gate count", "break the circuit", "remove inputs", "make simplification easier"]'::jsonb,3,'Choose whichever helps grouping.','original'),
('127.394.d.8.C',3,'A gate is called universal if it can be used to build:','["any other logic gate", "only clocks", "only power supplies", "only memory"]'::jsonb,0,'NAND and NOR are universal.','original'),
('127.394.d.8.C',4,'A NAND gate with its inputs tied together acts as a:','["OR gate", "NOT gate", "XOR gate", "AND gate"]'::jsonb,1,'NAND(A,A) = A''.','original')
) as v(code, diff, prompt, choices, ans, expl, src)
join public.teks_items i on i.code = v.code and i.is_standard
join public.teks_documents d on d.id = i.document_id and d.subject = 'Career Development' and d.language = 'en'
on conflict (fingerprint) do nothing;
