('127.395.d.4.A',3,'A robotics student should pass a safety test before working around:','["the library", "the bus", "moving robot arms and power tools", "the cafeteria"]'::jsonb,2,'Training precedes hazards.','original'),
('127.395.d.4.A',4,'Safety training for robot cells emphasizes staying out of the robot''s:','["paint booth", "parking lot", "lunch room", "work envelope"]'::jsonb,3,'The envelope is the reach area.','original'),
