('127.396.d.4.B',4,'Manual instructions about a robot''s restricted space tell workers to:','["stand inside it", "touch moving parts", "bypass guards", "stay outside its reach when it is powered"]'::jsonb,3,'Stay clear of live robots.','original'),
('127.396.d.4.C',3,'A robot lab''s battery charging area should have a:','["fire-safe charging bag or container", "open flame", "bucket of water on the charger", "pile of paper"]'::jsonb,0,'Containment limits fire risk.','original'),
('127.396.d.4.C',4,'Compressed air cylinders used in pneumatic robots are hazards because they are:','["too sweet", "under high pressure", "made of paper", "too cold"]'::jsonb,1,'Stored pressure can injure.','original'),
